args.new_string:
func (s *Service) deliver(ctx context.Context, d store.Delivery) {
	status, errText := 0, ""
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	e, eok := s.store.EventByID(d.EventID)
	sent := false
	switch {
	case !ok || !ep.Enabled:
		errText = "the endpoint is disabled or was deleted"
	case !eok:
		errText = "the event no longer exists"
	default:
		sent = true
		status, errText = s.send(ctx, ep, e)
	}
	now := s.clock.Now()
	gone := status == http.StatusGone
	if sent && gone {
		// The endpoint is gone: disable it, so its other pending deliveries are not sent.
		_, _ = s.store.UpdateWebhookEndpoint(ep.OrgID, ep.ID, func(x *store.WebhookEndpoint) error {
			x.Enabled, x.DisabledReason = false, "gone"
			return nil
		})
	}
	updated, _ := s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.Attempts++
		d.LastAttemptAt = &now
		d.NextAttemptAt = nil
		d.ResponseStatus = status
		d.Error = errText
		switch {
		case errText == "":
			d.Status = store.DeliverySucceeded
		case sent && !gone && d.Attempts < maxAttempts:
			next := now.Add(retryDelays[d.Attempts-1])
			d.Status = store.DeliveryPending
			d.NextAttemptAt = &next
		default:
			d.Status = store.DeliveryFailed
		}
		return nil
	})
	if sent && !gone && updated.Status == store.DeliveryFailed {
		s.notifyOwners(ctx, ep, errText, now)
	}
}

// notifyOwners emails every owner of the endpoint's organization that the endpoint keeps failing. It sends at most one such
